// Writes packages/naive/src/functions/pcf-roles.json from the role library (EE-232), or checks it.
//
//   node scripts/pcf-roles.ts            write the file from the pcf field of every role in packages/naive/src/roles/
//   node scripts/pcf-roles.ts --check    exit 1 when the file is not what the library generates, writing nothing
//
// The role side is the source and the element side is generated by packages/naive/src/engine/generators/pcf-roles.ts,
// so the link is held both ways and cannot drift. --root <dir> reads the library and pcf.json from, and writes into,
// another copy of the repository (used by packages/naive/src/engine/generators/pcf-roles-test.ts).

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { draft, FILE, format } from "../packages/naive/src/engine/generators/pcf-roles.ts";

const args = process.argv.slice(2);
const at = args.indexOf("--root");
const root = at >= 0 ? args[at + 1] : new URL("..", import.meta.url).pathname;
const d = draft({}, { root });
if (!d.ok || !("draft" in d) || !d.draft) {
  for (const e of d.errors) console.error(`FAIL  ${e}`);
  process.exit(1);
}
const bytes = format(d.draft);
if (args.includes("--check")) {
  let now = "";
  try { now = readFileSync(join(root, FILE), "utf8"); } catch { /* a missing file is stale */ }
  if (now !== bytes) {
    console.error(`FAIL  ${FILE} is stale: regenerate it with node scripts/pcf-roles.ts`);
    process.exit(1);
  }
  console.log(`${FILE} matches the role library: ${d.draft.elements.length} elements linked`);
} else {
  writeFileSync(join(root, FILE), bytes);
  console.log(`wrote ${FILE}: ${d.draft.elements.length} elements linked to roles`);
}
